/**
 * Sanitizes and validates architecture graph data generated by AI or user inputs
 */
const validateArchitectureGraph = (rawGraph, fallbackProjectName = 'Project') => {
  if (!rawGraph || typeof rawGraph !== 'object') {
    return createFallbackArchitecture(fallbackProjectName);
  }

  let { groups = [], nodes = [], edges = [], metadata = {} } = rawGraph;

  if (!Array.isArray(groups)) groups = [];
  if (!Array.isArray(nodes)) nodes = [];
  if (!Array.isArray(edges)) edges = [];

  // 1. Sanitize groups
  const groupMap = new Map();
  const validGroups = [];

  for (const group of groups) {
    if (!group || typeof group !== 'object') continue;
    const id = String(group.id || group.name || '')
      .toLowerCase()
      .replace(/[^a-z0-9_-]/g, '_');
    if (!id) continue;

    if (!groupMap.has(id)) {
      const sanitized = {
        id,
        label: String(group.label || group.name || id).trim(),
        description: group.description ? String(group.description).trim() : '',
      };
      groupMap.set(id, sanitized);
      validGroups.push(sanitized);
    }
  }

  // Ensure default group exists if none defined
  if (validGroups.length === 0) {
    const defaultGroup = { id: 'general', label: 'Core System', description: 'Main application components' };
    validGroups.push(defaultGroup);
    groupMap.set('general', defaultGroup);
  }

  // 2. Sanitize and deduplicate nodes
  const nodeMap = new Map();
  const validNodes = [];

  for (const node of nodes) {
    if (!node || typeof node !== 'object') continue;
    let id = String(node.id || node.name || node.path || '')
      .replace(/[^a-zA-Z0-9_-]/g, '_')
      .toLowerCase();
    if (!id) continue;

    // Check if group exists, else assign to first group
    let groupId = node.group ? String(node.group).toLowerCase().replace(/[^a-z0-9_-]/g, '_') : '';
    if (!groupMap.has(groupId)) {
      // Try to find matching group by label
      const matched = validGroups.find((g) => g.label.toLowerCase() === (node.group || '').toLowerCase());
      groupId = matched ? matched.id : validGroups[0].id;
    }

    if (!nodeMap.has(id)) {
      const sanitized = {
        id,
        label: String(node.label || node.name || id).trim(),
        type: String(node.type || 'component').toLowerCase(),
        path: node.path ? String(node.path).replace(/\\/g, '/').trim() : '',
        group: groupId,
        description: String(node.description || '').trim(),
        responsibility: String(node.responsibility || node.description || '').trim(),
      };
      nodeMap.set(id, sanitized);
      validNodes.push(sanitized);
    }
  }

  // If no nodes generated, create at least a root representation
  if (validNodes.length === 0) {
    return createFallbackArchitecture(fallbackProjectName);
  }

  // 3. Sanitize and validate edges
  const validEdges = [];
  const edgeKeySet = new Set();

  for (const edge of edges) {
    if (!edge || typeof edge !== 'object') continue;

    let source = String(edge.source || '').replace(/[^a-zA-Z0-9_-]/g, '_').toLowerCase();
    let target = String(edge.target || '').replace(/[^a-zA-Z0-9_-]/g, '_').toLowerCase();

    // Verify source and target nodes exist
    if (!nodeMap.has(source) || !nodeMap.has(target)) {
      // Attempt fuzzy match
      const sourceMatch = validNodes.find((n) => n.id === source || n.path.toLowerCase().includes(source) || n.label.toLowerCase() === source);
      const targetMatch = validNodes.find((n) => n.id === target || n.path.toLowerCase().includes(target) || n.label.toLowerCase() === target);
      if (sourceMatch && targetMatch) {
        source = sourceMatch.id;
        target = targetMatch.id;
      } else {
        continue; // Discard invalid edge
      }
    }

    if (source === target) continue; // Skip self loops for cleaner architecture

    const edgeKey = `${source}->${target}`;
    if (!edgeKeySet.has(edgeKey)) {
      edgeKeySet.add(edgeKey);
      validEdges.push({
        id: edge.id || `edge_${source}_to_${target}`,
        source,
        target,
        label: edge.label ? String(edge.label).trim() : 'connects to',
        type: String(edge.type || 'data_flow').toLowerCase(),
      });
    }
  }

  return {
    groups: validGroups,
    nodes: validNodes,
    edges: validEdges,
    metadata: {
      architecturalStyle: metadata.architecturalStyle || 'Modular Full-Stack Application',
      summary: metadata.summary || 'Architecture automatically analyzed by Dionysus AI',
      generatedAt: new Date().toISOString(),
      nodeCount: validNodes.length,
      edgeCount: validEdges.length,
      groupCount: validGroups.length,
    },
  };
};

/**
 * Fallback architecture if AI fails or repository has minimal code
 */
const createFallbackArchitecture = (projectName = 'Repository') => {
  return {
    groups: [
      { id: 'frontend', label: 'Frontend UI', description: 'Client-side interface' },
      { id: 'backend', label: 'Backend Server', description: 'Application logic & API' },
    ],
    nodes: [
      {
        id: 'client_app',
        label: `${projectName} Client`,
        type: 'component',
        path: 'client',
        group: 'frontend',
        description: 'Web client application interface',
        responsibility: 'Handles user interactions and presentation',
      },
      {
        id: 'server_app',
        label: `${projectName} Server`,
        type: 'service',
        path: 'server',
        group: 'backend',
        description: 'Backend API service',
        responsibility: 'Provides endpoints and business logic',
      },
    ],
    edges: [
      {
        id: 'edge_client_server',
        source: 'client_app',
        target: 'server_app',
        label: 'HTTP / REST API',
        type: 'api',
      },
    ],
    metadata: {
      architecturalStyle: 'Client-Server Architecture',
      summary: 'Basic two-tier architecture diagram',
      generatedAt: new Date().toISOString(),
      isFallback: true,
    },
  };
};

module.exports = {
  validateArchitectureGraph,
  createFallbackArchitecture,
};

